INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die CPU eine zentrale Kernkomponente der Hardware?', 2, '[{"text": "Ja", "correct": true, "because": "Verarbeitet Daten"}, {"text": "Nein", "correct": false, "because": "Sie ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt die CPU?', 3, '[{"text": "Befehle ausführen und Daten verarbeiten", "correct": true, "because": "Rechenleistung"}, {"text": "Daten dauerhaft speichern", "correct": false, "because": "Festplattenaufgabe"}, {"text": "Grafik darstellen", "correct": false, "because": "GPU-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die CPU ist das Herzstück eines Computers. b) Sie ist nur für Speicherung zuständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Verarbeitung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hauptkomponenten hat eine CPU?', 4, '[{"text": "Rechenwerk", "correct": true, "because": "Führt Berechnungen aus"}, {"text": "Unklare Teile", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Steuerwerk", "correct": true, "because": "Koordiniert Abläufe"}, {"text": "Register", "correct": true, "because": "Speichert temporäre Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Computer ohne CPU arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Verarbeitung fehlt"}, {"text": "Ja", "correct": false, "because": "Unmöglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die CPU in einem System?', 3, '[{"text": "Verarbeitung von Programmen", "correct": true, "because": "Führt Befehle aus"}, {"text": "Daten dauerhaft speichern", "correct": false, "because": "Festplattenaufgabe"}, {"text": "Netzwerkverbindung", "correct": false, "because": "Netzwerkkartenaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die CPU nur für Desktops relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in Notebooks, Servern"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat das Steuerwerk in der CPU?', 3, '[{"text": "Koordination der Befehlsausführung", "correct": true, "because": "Steuert Abläufe"}, {"text": "Grafikberechnung", "correct": false, "because": "GPU-Aufgabe"}, {"text": "Daten speichern", "correct": false, "because": "Speicheraufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die CPU hat mehrere Kerne. b) Sie arbeitet ohne Strom.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Strom nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne CPU in einem Computer?', 3, '[{"text": "System startet nicht", "correct": true, "because": "Verarbeitung fehlt"}, {"text": "Schnellere Datenverarbeitung", "correct": false, "because": "Unsinn"}, {"text": "Nur Bildschirm an", "correct": false, "because": "Kein Betrieb"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die CPU ohne RAM arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Arbeitsspeicher nötig"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine CPU?', 3, '[{"text": "Intel Core i5", "correct": true, "because": "Konkret und real"}, {"text": "Festplatte", "correct": false, "because": "Speicherkomponente"}, {"text": "Monitor", "correct": false, "because": "Ausgabegerät"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die CPU nur für Berechnungen zuständig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Steuerung"}, {"text": "Ja", "correct": false, "because": "Breitere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat eine moderne CPU?', 4, '[{"text": "Mehrere Kerne", "correct": true, "because": "Erhöht Leistung"}, {"text": "Keine Kühlung", "correct": false, "because": "Widerspricht Funktion"}, {"text": "Cache-Speicher", "correct": true, "because": "Schnellere Daten"}, {"text": "Hohe Taktfrequenz", "correct": true, "because": "Bestimmt Geschwindigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine CPU gekühlt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Verhindert Überhitzung"}, {"text": "Nein", "correct": false, "because": "Kühlung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Cache in der CPU?', 3, '[{"text": "Schneller Datenzugriff", "correct": true, "because": "Zwischenspeicher"}, {"text": "Dauerhafte Speicherung", "correct": false, "because": "Festplattenaufgabe"}, {"text": "Netzwerkverbindung", "correct": false, "because": "Netzwerkkartenaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine CPU ohne Betriebssystem arbeiten?', 2, '[{"text": "Ja", "correct": true, "because": "Grundfunktionen möglich"}, {"text": "Nein", "correct": false, "because": "Software steuert Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die CPU-Leistung?', 3, '[{"text": "Taktfrequenz", "correct": true, "because": "Bestimmt Geschwindigkeit"}, {"text": "Monitorgröße", "correct": false, "because": "Kein Einfluss"}, {"text": "Tastaturlayout", "correct": false, "because": "Keine Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) CPUs haben unterschiedliche Architekturen. b) Sie sind nur für Gaming geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit einsetzbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen einer leistungsstarken CPU?', 3, '[{"text": "Schnelle Datenverarbeitung", "correct": true, "because": "Fördert Effizienz"}, {"text": "Maximale Langsamkeit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Berechnungen", "correct": false, "because": "Fördert Leistung"}]');